package users

// The Postgres schema (corescope_users). A fresh schema is created at once
// in the state SQLite reaches after migrations v1..v8 (pgBaseline, recorded
// as version pgBaselineVersion); later versions are pgMigrations, which must
// track migrations one for one (see the comment there).
//
// Types per AGENTS.md: TEXT -> TEXT COLLATE "C" (byte order, as SQLite's
// BINARY), INTEGER -> BIGINT, INTEGER PRIMARY KEY -> BIGINT GENERATED BY
// DEFAULT AS IDENTITY (so a copy can keep its ids). Column order, defaults,
// CHECKs, foreign-key actions and index names are SQLite's. One addition:
// mail_events has no rowid on Postgres, so it gets an identity column of
// that name, which keeps eventsFor's "ORDER BY at, rowid" (insertion order)
// the same query on both backends.

// pgBaselineVersion is the SQLite schema version pgBaseline equals.
const pgBaselineVersion = 8

var pgBaseline = []string{
	`CREATE TABLE users (
		id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
		email TEXT COLLATE "C" NOT NULL UNIQUE,
		display_name TEXT COLLATE "C" NOT NULL,
		password_hash TEXT COLLATE "C" NOT NULL,
		role TEXT COLLATE "C" NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')),
		status TEXT COLLATE "C" NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','disabled')),
		created_at BIGINT NOT NULL,
		activated_at BIGINT,
		activated_by BIGINT,
		last_login_at BIGINT,
		email_bouncing BIGINT NOT NULL DEFAULT 0
	)`,
	`CREATE TABLE sessions (
		id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
		token_hash TEXT COLLATE "C" NOT NULL UNIQUE,
		user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
		csrf_token TEXT COLLATE "C" NOT NULL,
		created_at BIGINT NOT NULL,
		expires_at BIGINT NOT NULL,
		last_seen_at BIGINT NOT NULL,
		user_agent TEXT COLLATE "C" NOT NULL DEFAULT '',
		kind TEXT COLLATE "C" NOT NULL DEFAULT 'web' CHECK (kind IN ('web','device')),
		label TEXT COLLATE "C" NOT NULL DEFAULT '',
		scopes TEXT COLLATE "C" NOT NULL DEFAULT ''
	)`,
	`CREATE INDEX sessions_user ON sessions(user_id)`,
	`CREATE TABLE tokens (
		token_hash TEXT COLLATE "C" PRIMARY KEY,
		user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
		purpose TEXT COLLATE "C" NOT NULL CHECK (purpose IN ('activate','reset','email_change')),
		new_email TEXT COLLATE "C",
		expires_at BIGINT NOT NULL,
		used_at BIGINT
	)`,
	`CREATE INDEX tokens_user ON tokens(user_id, purpose)`,
	`CREATE TABLE audit_log (
		id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
		at BIGINT NOT NULL,
		actor_user_id BIGINT,
		action TEXT COLLATE "C" NOT NULL,
		target_user_id BIGINT,
		detail TEXT COLLATE "C" NOT NULL DEFAULT '{}'
	)`,
	`CREATE INDEX audit_target ON audit_log(target_user_id)`,
	`CREATE INDEX audit_actor ON audit_log(actor_user_id)`,
	`CREATE INDEX audit_at ON audit_log(at)`,
	`CREATE TABLE mail_log (
		id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
		user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
		to_email TEXT COLLATE "C" NOT NULL,
		purpose TEXT COLLATE "C" NOT NULL,
		provider_message_id TEXT COLLATE "C",
		sent_at BIGINT NOT NULL,
		last_event TEXT COLLATE "C" NOT NULL DEFAULT 'sent',
		last_event_at BIGINT NOT NULL,
		last_reason TEXT COLLATE "C" NOT NULL DEFAULT ''
	)`,
	`CREATE INDEX mail_user ON mail_log(user_id)`,
	`CREATE UNIQUE INDEX mail_msgid ON mail_log(provider_message_id) WHERE provider_message_id IS NOT NULL`,
	`CREATE TABLE mail_events (
		mail_id BIGINT NOT NULL REFERENCES mail_log(id) ON DELETE CASCADE,
		event TEXT COLLATE "C" NOT NULL,
		at BIGINT NOT NULL,
		reason TEXT COLLATE "C" NOT NULL DEFAULT '',
		rowid BIGINT GENERATED BY DEFAULT AS IDENTITY,
		UNIQUE (mail_id, event, at)
	)`,
	`CREATE TABLE user_settings (
		user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
		doc TEXT COLLATE "C" NOT NULL,
		revision BIGINT NOT NULL,
		generation TEXT COLLATE "C" NOT NULL,
		updated_at BIGINT NOT NULL
	)`,
	`CREATE TABLE proposals (
		id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
		kind TEXT COLLATE "C" NOT NULL,
		subject TEXT COLLATE "C" NOT NULL,
		status TEXT COLLATE "C" NOT NULL CHECK (status IN ('pending','approved','rejected','revoked')),
		proposer_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
		reviewer_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
		note TEXT COLLATE "C" NOT NULL DEFAULT '',
		created_at BIGINT NOT NULL,
		decided_at BIGINT
	)`,
	`CREATE UNIQUE INDEX proposals_kind_subject ON proposals(kind, subject)`,
	`CREATE INDEX proposals_status ON proposals(status)`,
	`CREATE TABLE notification_prefs (
		user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
		enabled BIGINT NOT NULL DEFAULT 1,
		events TEXT COLLATE "C" NOT NULL DEFAULT '',
		unsub_token TEXT COLLATE "C" NOT NULL UNIQUE,
		updated_at BIGINT NOT NULL
	)`,
	`CREATE TABLE notification_watches (
		user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
		pubkey TEXT COLLATE "C" NOT NULL,
		created_at BIGINT NOT NULL,
		PRIMARY KEY (user_id, pubkey)
	)`,
	`CREATE TABLE notification_state (
		user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
		event TEXT COLLATE "C" NOT NULL,
		subject TEXT COLLATE "C" NOT NULL,
		state TEXT COLLATE "C" NOT NULL,
		changed_at BIGINT NOT NULL,
		PRIMARY KEY (user_id, event, subject)
	)`,
	`CREATE TABLE companion_links (
		pubkey TEXT COLLATE "C" PRIMARY KEY,
		user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
		name TEXT COLLATE "C" NOT NULL DEFAULT '',
		linked_at BIGINT NOT NULL
	)`,
	`CREATE INDEX companion_links_user ON companion_links(user_id)`,
	`CREATE TABLE link_challenges (
		challenge_hash TEXT COLLATE "C" PRIMARY KEY,
		user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
		pubkey TEXT COLLATE "C" NOT NULL,
		expires_at BIGINT NOT NULL
	)`,
	`CREATE TABLE mqtt_logins (
		user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
		username TEXT COLLATE "C" NOT NULL UNIQUE,
		password_hash TEXT COLLATE "C" NOT NULL,
		password_enc TEXT COLLATE "C" NOT NULL,
		created_at BIGINT NOT NULL,
		revoked_at BIGINT,
		last_auth_at BIGINT
	)`,
	`CREATE TABLE observer_bindings (
		pubkey TEXT COLLATE "C" PRIMARY KEY,
		user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
		bound_at BIGINT NOT NULL,
		bound_by TEXT COLLATE "C" NOT NULL CHECK (bound_by IN ('auto','admin')),
		confirmed_at BIGINT
	)`,
	`CREATE INDEX observer_bindings_user ON observer_bindings(user_id)`,
}

// pgMigrations[i] upgrades the Postgres schema from version
// pgBaselineVersion+i to pgBaselineVersion+i+1, the same step as
// migrations[pgBaselineVersion+i] on SQLite. Forward-only, like migrations.
var pgMigrations = [][]string{
	{ // v9: rate_limits
		`CREATE TABLE rate_limits (
			key TEXT COLLATE "C" NOT NULL,
			window_start BIGINT NOT NULL,
			hits BIGINT NOT NULL,
			PRIMARY KEY (key, window_start)
		)`,
	},
}
